#include <stdio.h>
#include <stdlib.h>

// Weird struct with recursive pointer...
struct s { 
  struct s *s;
}; 

// Just classic c new struct function
static struct s *z(struct s* n) {
	struct s *t = n; // copy of original pointer
  n = malloc(sizeof(struct s)); // replacing with new struct?
	n->s = t; // assigning old copy to a new one
	return n;
}

// Counts length of sequence
static int pi (struct s *n) { 
  int x = 0;
  for(;n ;n=n-> s,x++);
  return x;
}

// Create sequence on length n 
static struct s* ip(int n){
  struct s *s=0;

  for(int i=0;i<n;i++){
    s = z(s);
  }

  return s;
}

// Go into inner struct until n or o reach end. Return pointer of longer sequence
static int pc(struct s* n,struct s* o){
  for(;n&&o;n=n->s,o=o->s);
  return n||o;
}

// Encryption process
static void df(int*p){
  // I guess int is missed here...?
  register int n = 128;
  switch(1024%8) { // 1024 % 8 == 0
    case 0: do{
      *p^=0x63;p++;
      case 7:*p^=48;p++;
      case 6:
      case 5:*p<<=4;p++;
      case 4:*p<<=2;p++;
      case 3:*p*=55;p++;
      case 2:*p-=-97;p++;
      case 1: *p+=44;p++;
    } while(--n>0);
  }
}



static void reverse_df(int* p) {
    register int n = 128;
    switch(1024 % 8) { // 1024 % 8 == 0
        case 0: do {
            *p ^= 0x63; p++;
            *p ^= 48; p++;
            *p >>= 4; p++;
            *p >>= 2; p++;
            *p /= 55; p++;
            *p -= 97; p++;
            *p -= 44; p++;
        } while(--n > 0);
    }
}

// First call from main
// Kinda memcpy
static void dc(int*d,char*s){
  register int n=(1024+7)/8;
  switch (1024%8){ // 1024 % 8 == 0
    case 0: do{
      *d++=*s++;
      case 7:* d++=*s++;
      case 6:*d++=*s++;
      case 5:*d++=*s++;
      case 4:*d++=*s++;
      case 3:*d++=*s++;
      case 2:*d++=*s++;
      case 1:*d++=*s++;
    } while(--n>0);
  }
}

