int main(void){
  // Read some string into b
  static char b[1024]; // zero by default
	static int i[1024];  // same
	fgets(b,1024,stdin); // our secret key

  // Converts each char into integer
  dc(i,b);

  // Encrypts i using special cycle algorithm, as it processed only 8 ints, after that algorihtm repeats
	df(i); 

  // As our goal is to make i be always different from a seq depths
  // we can extract computation part into separate c file
  // and try to find key which will produce it correctly

  // After performing all this operations we can finally compute ch(i) and inverse it
	return !ch(i); // <- i is an array of lengths of sequences
}
